// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz: from, v, and a bounded length for the _tos array
    function testFuzz_property(address from, uint256 v, uint256 len) public {
        // keep len small but allow 0..8; bound returns uint256 so cast safely
        uint256 bounded = bound(len, 0, 8);
        address[] memory tos = new address[](bounded);
        // fill with the recorder contract address (we will deploy below)
        ReverterRecorder rec = new ReverterRecorder();
        for (uint i = 0; i < bounded; i++) {
            tos[i] = address(rec);
        }

        // require non-empty per contract precondition; if empty, skip by assumption
        vm.assume(bounded > 0);

        // fund the test caller so low-level calls have no gas/value issues (not strictly needed)
        vm.deal(address(this), 1 ether);

        // The helper will accept exactly bounded calls; it will revert if called more than that.
        rec.setExpectedCalls(uint8(bounded));

        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for the correct contract, calling transfer with any non-empty tos that contains
        // a callee which accepts exactly tos.length calls will NOT revert. The mutant that uses i<=_tos.length
        // can produce an extra call and thus may revert. We assert the correct contract never reverts here.
        assertTrue(ok);
    }
}

// Helper that accepts exactly N calls; if called more than N times it reverts.
contract ReverterRecorder {
    uint256 public calls;
    uint8 public expected;
    function setExpectedCalls(uint8 n) external {
        expected = n;
        calls = 0;
    }
    // match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        // record and enforce expected count
        calls++;
        if (calls > expected) revert("too many calls");
        return true;
    }
    // fallback to catch malformed calls and revert (safety)
    fallback() external payable {
        revert("bad call");
    }
}
